const n = parseInt(readline()) / 50;
const type = readline();
const cup = [
  "#...........#",
  "#...........#",
  " #.........#",
  "  #.......#",
  "   #.....#",
  "    #####"];

for (let i = 0; i < n; i++) cup[i] = cup[i].replaceAll(".", " ");
if (type == "cappuccino")
  cup[n] = cup[n].replaceAll(".", "~");

console.log(cup.join("\n"));
